/**
 * Parity against librosa pYIN reference output (generated by the phase 0
 * validation study, see TuningHelper/projects/validate_trackers/).
 * Fixtures: tests/fixtures/audio/<name>_12s.wav + tests/fixtures/reference/<name>_12s.json.
 * Skips when fixtures are absent.
 */
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { analyse, DEFAULT_PARAMS } from '../../src/dsp/analyse';
import { hzToCents } from '../../src/dsp/cents';
import { median } from '../../src/dsp/stats';

interface Reference {
  sr: number; frame: number; hop: number; fmin: number; fmax: number;
  t: number[]; f0_pyin: (number | null)[]; voiced_prob: number[]; rms_db: number[];
  notes: { start: number; end: number; median_cents: number; median_hz: number }[];
}

function readWav(path: string): { samples: Float32Array; sampleRate: number } {
  const b = readFileSync(path);
  if (b.toString('ascii', 0, 4) !== 'RIFF') throw new Error('not a WAV');
  let off = 12, fmt: { ch: number; sr: number; bits: number } | null = null, data: Buffer | null = null;
  while (off < b.length) {
    const id = b.toString('ascii', off, off + 4), size = b.readUInt32LE(off + 4);
    if (id === 'fmt ') fmt = { ch: b.readUInt16LE(off + 10), sr: b.readUInt32LE(off + 12), bits: b.readUInt16LE(off + 22) };
    if (id === 'data') data = b.subarray(off + 8, off + 8 + size);
    off += 8 + size + (size & 1);
  }
  if (!fmt || !data) throw new Error('bad WAV');
  if (fmt.bits !== 16) throw new Error('only 16-bit WAV supported in test reader');
  const n = data.length / 2 / fmt.ch;
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let c = 0; c < fmt.ch; c++) s += data.readInt16LE((i * fmt.ch + c) * 2) / 32768;
    out[i] = s / fmt.ch;
  }
  return { samples: out, sampleRate: fmt.sr };
}

const refDir = resolve('tests/fixtures/reference');
const audioDir = resolve('tests/fixtures/audio');
const names = existsSync(refDir)
  ? readdirSync(refDir).filter((f) => f.endsWith('_12s.json')).map((f) => f.replace('.json', ''))
    .filter((n) => existsSync(resolve(audioDir, `${n}.wav`)))
  : [];

describe.skipIf(names.length === 0)('parity with librosa pyin', () => {
  for (const name of names) {
    for (const tracker of ['mpm', 'yin'] as const) {
      it(`${name} / ${tracker}: per-note medians within 5 cents, frames within 3 cents`, () => {
        const ref: Reference = JSON.parse(readFileSync(resolve(refDir, `${name}.json`), 'utf8'));
        const wav = readWav(resolve(audioDir, `${name}.wav`));
        expect(wav.sampleRate).toBe(ref.sr);
        const res = analyse(wav.samples, wav.sampleRate, {
          ...DEFAULT_PARAMS, tracker, frameSize: ref.frame, hop: ref.hop, fmin: ref.fmin, fmax: ref.fmax,
          onsetDiscardS: 0, medianFrames: 1, clarityMin: 0.8,
        });

        // Frame-level: where both are voiced, cents difference should be small.
        const diffs: number[] = [];
        const n = Math.min(ref.t.length, res.frames.t.length);
        let both = 0, refVoiced = 0;
        for (let i = 0; i < n; i++) {
          const rf = ref.f0_pyin[i];
          if (rf != null && ref.voiced_prob[i] > 0.5) refVoiced++;
          const mf = res.frames.f0[i];
          if (rf != null && ref.voiced_prob[i] > 0.5 && Number.isFinite(mf)) {
            both++;
            diffs.push(hzToCents(mf, rf));
          }
        }
        expect(both / Math.max(1, refVoiced), 'fraction of pyin-voiced frames also voiced here').toBeGreaterThan(0.7);
        const absDiffs = diffs.map(Math.abs);
        expect(median(absDiffs), 'median |cents diff| per frame').toBeLessThan(3);
        const octaveErr = absDiffs.filter((d) => d > 600).length / Math.max(1, absDiffs.length);
        expect(octaveErr, 'octave-error fraction').toBeLessThan(0.05);

        // Note-level: match reference notes by time overlap.
        let matched = 0;
        for (const rn of ref.notes) {
          const mine = res.notes.find((m) => Math.min(m.endT, rn.end) - Math.max(m.startT, rn.start) > 0.5 * (rn.end - rn.start));
          if (!mine) continue;
          matched++;
          expect(Math.abs(mine.medianCentsAbs - rn.median_cents), `note at ${rn.start.toFixed(2)} s`).toBeLessThan(5);
        }
        expect(matched / Math.max(1, ref.notes.length), 'fraction of reference notes matched').toBeGreaterThan(0.7);
      });
    }
  }
});
